mapper.select:
SELECT OM.ACC_ORG_CODE AS ORGANIZATION_CODE ,OM.ORG_NAME_LOCAL ,EM.EMPLOYEE_NUMBER ,EM.FULL_NAME_LOCAL ,lgvhr_common_pkg.decode_lookup('IF_VIETNAM_GRADE_TITLE', EM.grade_title) AS "grade_title" ,to_char(TACN.EFFECTIVE_START_DATE, 'yyyy-mm-dd') AS EFFECTIVE_START_DATE ,to_char(TACN.EFFECTIVE_END_DATE, 'yyyy-mm-dd') AS EFFECTIVE_END_DATE ,OM.ORGANIZATION_ID FROM EMP_MASTER EM ,ORG_MASTER OM ,TB_ATT_CONTRACT_N TACN WHERE EM.EMPLOYEE_NUMBER = TACN.TIME_ATTEND_CONTACT_USER_ID AND TACN.Organization_Id = OM.Organization_Id AND OM.ORG_END_DATE IS NULL AND EM.FSE_YN = 'N' AND EM.FLSA_YN = 'N'
AND OM.ACC_ORG_CODE = #{orgCode}
AND EM.EMPLOYEE_NUMBER = #{employeeNo}

mapper.update:
DELETE FROM TB_ATT_CONTRACT_N
WHERE TIME_ATTEND_CONTACT_USER_ID = #{employeeNumber}
AND   ORGANIZATION_ID             = #{organizationId}
